func (n *Node) tick() {
  if n.state == Leader {
    n.lastHB = time.Now()
    n.broadcast(Heartbeat{Term: n.term})
    return
  }
  if time.Since(n.lastHB) > n.timeout {
    n.term++
    n.state = Candidate
    votes := n.requestVotes(n.term)
    if votes > len(n.peers)/2 {
      n.state = Leader
    }
  }
}
func (n *Node) onHeartbeat(h Heartbeat) {
  if h.Term >= n.term { n.term = h.Term; n.state = Follower; n.lastHB = time.Now() }
}
