struct Node { std::atomic<Node*> next; T val; };
std::atomic<Node*> head_, tail_;
void push(Node* n) {
  n->next.store(nullptr, std::memory_order_relaxed);
  Node* prev = head_.exchange(n, std::memory_order_relaxed);
  prev->next.store(n, std::memory_order_relaxed);
}
bool pop(T& out) {
  Node* t = tail_.load(std::memory_order_relaxed);
  Node* nx = t->next.load(std::memory_order_relaxed);
  if (!nx) return false;
  out = nx->val;
  tail_.store(nx, std::memory_order_relaxed);
  delete t;
  return true;
}

